(()=>{'use strict';const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));function html(id){const a=AnnotatedAnswers[id];if(!a)return '';return `<details class="annotated-answer"><summary>Compare a weak answer with an annotated strong answer</summary><p><b>Worked example:</b> ${esc(a.prompt)}</p><div class="answer-weak"><h4>Needs improvement</h4><blockquote>${esc(a.weak)}</blockquote><p>${esc(a.why)}</p></div><h4>Stronger answer · three marking points</h4><ol class="answer-clauses">${a.clauses.map((s,i)=>`<li><p>${esc(s)}</p><aside><b>Why this earns credit:</b> ${esc(a.notes[i])}</aside></li>`).join('')}</ol><p class="small">Illustrative practice marking, not an official examiner’s judgement. Use your own scientifically correct wording. Try writing an answer before opening the example.</p></details>`}window.AnswerGuide={html};})();
